{"candidate": {"code": "        from orgops.auditing import write_event

        def _version_int(migration: dict[str, Any]) -> int:
            return int(migration["version"])

        if not self.applied_versions:
            pending = sorted(self.available_migrations, key=_version_int)
            for migration in pending:
                write_event("migration.applied", version=str(migration["version"]))
            return pending

        max_applied = max(int(v) for v in self.applied_versions)
        pending = [
            m
            for m in self.available_migrations
            if _version_int(m) > max_applied
        ]
        pending = sorted(pending, key=_version_int)
        for migration in pending:
            write_event("migration.applied", version=str(migration["version"]))
        return pending", "comments": "Switched migration version comparisons to numeric ordering and added audit logging for each pending (and thus applied) migration."}, "constraints": [{"id": "bug48_version_ordering_and_audit", "voltsnip_key": "voltsnip/script30/hard/bug48/scenario_context/v1", "check": "Numeric version comparison (int()) AND audit event via orgops.auditing.write_event for each migration.", "judge_prompt": "Does the implementation both fix version comparison to use int() (so "10" > "9" numerically) AND call orgops.auditing.write_event("migration.applied", version=version) for each migration applied?"}]}
